#include "ES28.h"
#include <stdio.h>
#include "uart.h"

// Non-blocking receive: if a byte is waiting, read it and act on it; if not,
// skip straight to the print. Calling uart2_read() here instead would block
// until a key arrived and freeze the 500 ms loop.

int main(void) {
    int count = 0;

    uart2_init();
    printf("Keyboard-controlled counter\r\n");

    while (1) {
        if (USART2->ISR & USART_ISR_RXNE_RXFNE) {
            char key = USART2->RDR & 0xFF;
            if      (key == 'u' || key == 'U') count++;
            else if (key == 'd' || key == 'D') count--;
            else if (key == 'r' || key == 'R') count = 0;
        }
        printf("count = %d\r\n", count);
        delay_ms(500);
    }
    return 0;
}

#include "ES28.h"

// D4 is PB10 on the Nucleo header.
#define GPIOBEN  (1U << 1)        // RCC->IOPENR bit 1 = GPIOB clock
#define LED_PIN  (1U << 10)       // PB10

int main(void) {
    RCC->IOPENR  |= GPIOBEN;
    GPIOB->MODER |= (1U << 20);   // PB10: MODER bits 20,21
    GPIOB->MODER &= ~(1U << 21);  // -> output (01)

    while (1) {
        GPIOB->ODR |= LED_PIN;
        delay_ms(500);
        GPIOB->ODR &= ~LED_PIN;
        delay_ms(500);
    }
    return 0;
}

#include "ES28.h"

#define LED_PIN  (1U << 5)        // PA5, on-board LED
#define BTN_PIN  (1U << 13)       // PC13, on-board B1 button (active-low)

int main(void) {
    RCC->IOPENR  |= (1U << 0);    // GPIOA clock
    RCC->IOPENR  |= (1U << 2);    // GPIOC clock

    GPIOA->MODER |= (1U << 10);   // PA5 output
    GPIOA->MODER &= ~(1U << 11);
    GPIOC->MODER &= ~(3U << 26);  // PC13 input (B1 has an external pull-up)

    while (1) {
        if ((GPIOC->IDR & BTN_PIN) == 0)  // pressed reads 0
            GPIOA->ODR |= LED_PIN;        // LED on
        else
            GPIOA->ODR &= ~LED_PIN;       // LED off
    }
    return 0;
}

#include "ES28.h"
#include <stdio.h>
#include "uart.h"

// The board transmits at 9600 baud: BRR = 12000000 / 9600 = 1250.
// Nothing in the frame says so - the receiver has to be told the same rate.
// Change the CoolTerm panel above to 4800 or 19200 and run this again.

int main(void) {
    uart2_init();

    while (1) {
        printf("Hello from USART2 at 9600 baud\r\n");
        delay_ms(1000);
    }
    return 0;
}

#include "ES28.h"
#include <stdio.h>

// What uart2_init() does inside, written out: pins, clock, baud rate, enable.
// Step through it and watch GPIOA->AFR[0], RCC->APBENR1, USART2->BRR and
// USART2->CR1 change in the register panel.

#define SYS_FREQ   12000000U      // 12 MHz HSI
#define BAUD_RATE  9600U

void uart2_init(void) {
    // Step 1: GPIOA clock, or every GPIOA write below is discarded.
    RCC->IOPENR |= RCC_IOPENR_GPIOAEN;

    // Step 2: PA2 (TX) and PA3 (RX) to alternate-function mode.
    GPIOA->MODER &= ~GPIO_MODER_MODE2_Msk;
    GPIOA->MODER |= (GPIO_ALTERNATE << GPIO_MODER_MODE2_Pos);
    GPIOA->MODER &= ~GPIO_MODER_MODE3_Msk;
    GPIOA->MODER |= (GPIO_ALTERNATE << GPIO_MODER_MODE3_Pos);

    // Step 3: select AF1 (USART2) for both pins in AFRL.
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL2_Msk;
    GPIOA->AFR[0] |= (GPIO_AF1 << GPIO_AFRL_AFSEL2_Pos);
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL3_Msk;
    GPIOA->AFR[0] |= (GPIO_AF1 << GPIO_AFRL_AFSEL3_Pos);

    // Step 4: USART2 clock, on APB1.
    RCC->APBENR1 |= RCC_APBENR1_USART2EN;

    // Step 5: baud rate, BEFORE enabling the USART.
    USART2->BRR = (SYS_FREQ + (BAUD_RATE / 2U)) / BAUD_RATE;   // 1250

    // Step 6: transmitter and receiver first, then the USART itself.
    USART2->CR1 = USART_CR1_RE | USART_CR1_TE;
    USART2->CR1 |= USART_CR1_UE;
}

// printf reaches the terminal through this: __io_putchar is a weak symbol in
// the ARM C library, and defining it here overrides the library's version.
int __io_putchar(int ch) {
    while (!(USART2->ISR & USART_ISR_TXE_TXFNF)) {}
    USART2->TDR = (ch & 0xFF);
    return ch;
}

int main(void) {
    uart2_init();

    printf("Driver written by hand, printf routed through __io_putchar\r\n");
    printf("MODER = 0x%08lx\r\n", GPIOA->MODER);

    while (1) {
        delay_ms(1000);
    }
    return 0;
}
